output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_carts_between_facing_shelves",
    "text": "A shopper must not bring a cart into an aisle flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenFacingShelves"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_narrow_shelf_aisle_with_cart",
    "text": "A shopper pushing a cart must not move into a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEnteringNarrowShelfAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "narrowShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEnteringNarrowShelfAisle"
    }
  },
  {
    "id": "retrieve_any_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "retrieve_cart_after_returning_from_single_file_aisle",
    "text": "After returning on foot from a single-file shelf aisle to the wider aisle, the shopper must pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkingBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "returnedFromSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisle",
              "S"
            ]
          },
          "post": "cartParkingBay"
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnedFromSingleFileAisle",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cartless_movement_only_for_entrance_or_narrow_excursion",
    "text": "Moving without a cart is permitted only in the entrance cart area or as part of a narrow-aisle excursion.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartParkingBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cartlessMovementAllowedHere": {
          "or": [
            "entranceCartArea",
            "singleFileAisle",
            "cartParkingBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "cartlessMovementAllowedHere"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_pickups_require_cart",
    "text": "Items taken from shelves along wider aisles must be collected while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart_before_shopping",
    "text": "A shopper is obliged to take a cart from the entrance cart area before proceeding with the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cartPickupCell": "at(1,7)"
      },
      "events": {
        "takeEntranceCart": {
          "pre": {
            "and": [
              "cartPickupCell",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeEntranceCart"
    }
  }
]
